import type { Metadata } from "next";
import "./globals.css";
export const metadata: Metadata = { title: "MarginGhost — Supplier Invoice Investigation", description: "Find the money hidden in supplier invoices. Compare invoices against contracts and purchase orders with source cited evidence." };
export default function RootLayout({children}: Readonly<{children: React.ReactNode}>) {return <html lang="en"><body>{children}</body></html>}
:root {
  color-scheme: light;
  --paper: #f5f4ef;
  --surface: #fffefa;
  --surface-muted: #f9f8f3;
  --ink: #222b25;
  --muted: #737b73;
  --subtle: #969c94;
  --line: #e4e5dc;
  --line-strong: #d5d9cf;
  --forest: #234d3a;
  --forest-deep: #183a2a;
  --forest-wash: #edf3ed;
  --amber: #855c1d;
  --amber-wash: #fbf4e6;
  --red: #8b4c42;
  --red-wash: #faf0ed;
  --sans: "Aptos", "Segoe UI", Arial, sans-serif;
  --serif: "Iowan Old Style", "Palatino Linotype", "Book Antiqua", Georgia, serif;
  font-family: var(--sans);
  background: var(--paper);
  color: var(--ink);
  font-synthesis: none;
  text-rendering: optimizeLegibility;
}

* { box-sizing: border-box; }
html { scroll-behavior: smooth; scroll-padding-top: 26px; }
body { margin: 0; min-width: 320px; background: var(--paper); }
button, input { font: inherit; }
button { cursor: pointer; }
a { color: inherit; }
button:focus-visible, a:focus-visible, input:focus-visible, summary:focus-visible {
  outline: 3px solid #8ba991;
  outline-offset: 3px;
}
::selection { background: #dce8dc; color: var(--forest-deep); }

.shell { width: min(1160px, 100% - 64px); margin: 0 auto; }
.topbar {
  min-height: 70px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 24px;
  border-bottom: 1px solid var(--line);
}
.brand { display: inline-flex; align-items: center; gap: 10px; color: var(--ink); text-decoration: none; font-size: 15px; font-weight: 700; letter-spacing: -.45px; white-space: nowrap; }
.brand small, footer small { margin-left: 4px; color: var(--subtle); font: 500 9px var(--sans); letter-spacing: .02em; }
.brand-icon { width: 29px; height: 29px; display: grid; place-items: center; border-radius: 7px; background: var(--forest); color: #fff; font: 500 17px var(--serif); }
.main-nav { display: flex; align-items: center; gap: 29px; margin-left: auto; }
.main-nav a { color: #606a61; text-decoration: none; font-size: 11px; transition: color .16s ease; }
.main-nav a:hover { color: var(--forest); }
.mode-pill { display: inline-flex; align-items: center; gap: 7px; padding: 7px 10px; border: 1px solid #d6e0d6; border-radius: 99px; background: #f6faf5; color: var(--forest); font-size: 9px; font-weight: 600; white-space: nowrap; }
.mode-pill i { width: 6px; height: 6px; border-radius: 50%; background: #568162; }
.local-pill { border-color: var(--line); background: var(--surface); color: #606a61; }
.local-pill i { background: #8a9589; }

.hero { max-width: 780px; padding: 48px 0 37px; }
.eyebrow, .step, .scenario-index, .evidence-meta, .source-pages { font-size: 9px; font-weight: 600; letter-spacing: .09em; text-transform: uppercase; }
.eyebrow { display: flex; align-items: center; gap: 9px; color: var(--forest); }
.dot { width: 6px; height: 6px; border-radius: 50%; background: #6a9273; }
.hero h1 { max-width: 750px; margin: 15px 0 9px; color: #202922; font: 400 clamp(40px, 5.5vw, 61px)/.99 var(--serif); letter-spacing: -.045em; }
.hero > p { max-width: 580px; margin: 0; color: #626c63; font-size: 14px; line-height: 1.65; }
.hero-action { display: inline-flex !important; width: max-content; margin-top: 20px; text-decoration: none; }
.hero-note { display: flex; align-items: center; gap: 9px; margin-top: 13px; color: var(--subtle); font-size: 9px; }
.hero-note span { color: #b7bcb4; }
.nav-cta { display: inline-flex; align-items: center; gap: 10px; padding: 9px 12px; border: 1px solid #d7e1d6; border-radius: 5px; color: var(--forest); text-decoration: none; font-size: 10px; font-weight: 600; white-space: nowrap; }
.nav-cta:hover, .secondary-button:hover { background: #f1f6f0; }
.product-hero { padding: 54px 0 50px; }
.product-hero-grid { display: grid; grid-template-columns: minmax(0, 1.5fr) minmax(260px, .7fr); align-items: center; gap: clamp(30px, 7vw, 90px); margin-top: 17px; }
.product-hero h1 { max-width: 690px; margin: 0; color: #202922; font: 400 clamp(44px, 6.6vw, 74px)/.98 var(--serif); letter-spacing: -.05em; }
.product-hero-grid > div > p { max-width: 550px; margin: 18px 0 0; color: #626c63; font-size: 14px; line-height: 1.7; }
.product-actions { display: flex; align-items: center; flex-wrap: wrap; gap: 12px; margin-top: 21px; }
.secondary-button { min-height: 40px; display: inline-flex; align-items: center; gap: 15px; padding: 0 14px; border: 1px solid var(--line-strong); border-radius: 5px; color: #4d6250; text-decoration: none; font-size: 10px; font-weight: 600; }
.hero-proof { padding: 21px; border: 1px solid #dfe5dc; border-radius: 8px; background: #fbfcf8; box-shadow: 0 12px 36px #273d2610; }
.proof-label { color: #7c887c; font-size: 8px; font-weight: 700; letter-spacing: .1em; }
.proof-amount { margin-top: 20px; color: var(--forest); font: 500 43px/1 var(--serif); letter-spacing: -.04em; }
.hero-proof > strong { display: block; margin-top: 6px; color: #344137; font-size: 11px; }
.hero-proof > p { margin: 6px 0 14px; color: #798278; font-size: 9px; line-height: 1.55; }
.proof-rule { display: flex; justify-content: space-between; gap: 12px; padding: 9px 0; border-top: 1px solid #e9ece5; color: #818a80; font-size: 8px; }
.proof-rule b { color: #455448; font-weight: 600; text-align: right; }
.hero-proof > small { display: block; margin-top: 10px; color: #979e94; font-size: 7px; }
.how-section { padding: 25px 0 40px; border-top: 1px solid var(--line); }
.how-section .section-heading h2 { font-size: 31px; }
.how-grid { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 12px; }
.how-card { min-height: 150px; padding: 17px; border: 1px solid var(--line); border-radius: 7px; background: var(--surface); }
.how-card > span { color: #6e886f; font: 500 19px var(--serif); }
.how-card h3 { margin: 14px 0 5px; color: #344137; font: 500 18px var(--serif); }
.how-card p { max-width: 300px; margin: 0; color: #778075; font-size: 9px; line-height: 1.65; }
.product-cta { display: flex; align-items: center; justify-content: space-between; gap: 28px; margin: 9px 0 12px; padding: 21px; border: 1px solid #dce5da; border-radius: 8px; background: #f1f5ee; }
.product-cta h2 { margin: 6px 0 5px; color: #28372c; font: 500 25px var(--serif); }
.product-cta p { max-width: 470px; margin: 0; color: #737e72; font-size: 9px; line-height: 1.55; }
.product-cta .product-actions { flex: 0 0 auto; margin: 0; }
.primary-button { min-height: 40px; display: inline-flex; align-items: center; justify-content: center; gap: 18px; padding: 0 16px; border: 1px solid var(--forest); border-radius: 5px; background: var(--forest); color: #fff; font-size: 11px; font-weight: 600; transition: background .16s ease, border-color .16s ease, transform .16s ease; }
.primary-button:hover:not(:disabled) { transform: translateY(-1px); border-color: var(--forest-deep); background: var(--forest-deep); }
.primary-button:disabled { opacity: .48; cursor: not-allowed; }

.workspace { display: grid; grid-template-columns: minmax(0, 1.55fr) minmax(270px, .8fr); gap: 18px; align-items: start; }
.card { border: 1px solid var(--line); border-radius: 9px; background: var(--surface); }
.upload-card { padding: 23px 24px; }
.section-head, .section-heading { display: flex; align-items: flex-start; justify-content: space-between; gap: 20px; }
.step { color: #7c887c; }
.section-head h2, .section-heading h2, .status-card h2, .demo-card h2, .evidence-card h2 { margin: 5px 0 0; color: var(--ink); font: 500 24px/1.1 var(--serif); letter-spacing: -.025em; }
.quiet-pill { align-self: flex-start; padding: 6px 9px; border: 1px solid var(--line); border-radius: 99px; color: #717a70; font-size: 9px; white-space: nowrap; }
.section-copy { max-width: 620px; margin: 10px 0 20px; color: var(--muted); font-size: 11px; line-height: 1.65; }
.doc-group { min-width: 0; margin-top: 11px; padding: 13px 14px 10px; border: 1px solid var(--line); border-radius: 7px; background: #fff; }
.doc-invoice { grid-column: 1 / -1; }
.upload-card { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); column-gap: 11px; }
.upload-card > .section-head, .upload-card > .section-copy, .upload-card > .identity-note, .upload-card > .error-box, .upload-card > .demo-banner, .upload-card > .submit-row { grid-column: 1 / -1; }
.group-title { display: flex; align-items: center; gap: 10px; padding: 0 0 10px; border-bottom: 1px solid #eeefe9; }
.doc-symbol { width: 26px; height: 26px; display: grid; flex: 0 0 auto; place-items: center; border: 1px solid #dce5dc; border-radius: 6px; background: var(--forest-wash); color: var(--forest); font: 600 10px var(--sans); }
.doc-purchase_order .doc-symbol { border-color: #e8e1d1; background: #f7f3e9; color: #816535; }
.doc-invoice .doc-symbol { border-color: #dce4e9; background: #f0f4f5; color: #4c6970; }
.doc-amendment .doc-symbol { border-color: #e6dfd1; background: #f7f3ec; color: #7b694d; }
.doc-heading { display: grid; gap: 2px; min-width: 0; }
.doc-heading strong { font-size: 11px; font-weight: 600; }
.doc-heading small { color: var(--muted); font-size: 8px; }
.doc-count { margin-left: auto; color: var(--subtle); font-size: 8px; white-space: nowrap; }
.doc-count.is-ready { color: var(--forest); }
.file-row { display: flex; align-items: flex-start; gap: 10px; min-width: 0; padding: 11px 0 7px; border-bottom: 1px solid #f0f0eb; }
.pdf-icon, .source-doc-mark { width: 27px; height: 29px; display: grid; flex: 0 0 auto; place-items: center; border: 1px solid #eadbd7; border-radius: 4px; background: #fbf4f1; color: #92574b; font-size: 7px; font-weight: 700; letter-spacing: .04em; }
.file-main { flex: 1; min-width: 0; }
.file-line { display: flex; align-items: center; gap: 8px; min-width: 0; }
.file-line strong { overflow: hidden; color: #364037; font-size: 10px; font-weight: 600; text-overflow: ellipsis; white-space: nowrap; }
.file-line > span { flex: 0 0 auto; color: var(--subtle); font-size: 8px; }
.id-label { display: flex; flex-wrap: wrap; align-items: center; gap: 6px; margin-top: 7px; color: #778076; font-size: 8px; }
.id-label input { width: min(180px, 100%); min-width: 100px; padding: 5px 7px; border: 1px solid var(--line); border-radius: 4px; background: #fff; color: var(--ink); font-size: 9px; }
.id-label input::placeholder { color: #a4aaa2; }
.file-status { display: block; margin-top: 5px; font-size: 8px; }
.status-ready { color: #54705a; }
.status-pending { color: #9a7550; }
.row-actions { display: flex; flex: 0 0 auto; gap: 8px; padding-top: 2px; white-space: nowrap; }
.text-action { padding: 3px 0; border: 0; background: transparent; color: var(--forest); font-size: 9px; font-weight: 600; }
.text-action:hover { text-decoration: underline; }
.text-action.remove { color: #838a81; }
.hidden-file, .add-button input { position: absolute; width: 1px; height: 1px; overflow: hidden; clip: rect(0, 0, 0, 0); white-space: nowrap; }
.add-button { display: inline-flex; align-items: center; gap: 7px; margin: 9px 0 2px; padding: 7px 9px; border: 1px solid var(--line); border-radius: 4px; background: #fff; color: #536b58; font-size: 9px; font-weight: 600; cursor: pointer; transition: background .16s ease, border-color .16s ease; }
.add-button:hover { border-color: #bdcdbd; background: #f7faf6; }
.progress-track { height: 3px; overflow: hidden; margin-top: 8px; border-radius: 3px; background: #e9eee8; }
.progress-track span { display: block; height: 100%; border-radius: inherit; background: #527a5b; transition: width .2s ease; }
.identity-note { display: flex; align-items: flex-start; gap: 9px; margin-top: 17px; padding: 10px 11px; border: 1px solid #e9ebe4; border-radius: 5px; background: var(--surface-muted); color: #70796f; font-size: 9px; line-height: 1.55; }
.note-mark { width: 15px; height: 15px; display: grid; flex: 0 0 auto; place-items: center; border: 1px solid #b9c2b6; border-radius: 50%; color: #697b69; font: 600 9px var(--serif); }
.submit-row { display: flex; align-items: center; gap: 12px; margin-top: 14px; }
.submit-hint { color: #899087; font-size: 8px; }
.error-box, .warnings-box { margin-top: 12px; padding: 11px 12px; border: 1px solid #ead5d0; border-radius: 5px; background: #fff8f6; color: #80483e; font-size: 10px; }
.error-box p, .warnings-box p { margin: 5px 0 0; line-height: 1.5; }
.demo-banner { margin-top: 11px; padding: 9px 10px; border: 1px solid #dce5da; border-radius: 5px; background: #f2f6ef; color: #536b54; font-size: 9px; line-height: 1.5; }
.side-column { display: grid; gap: 13px; }
.status-card, .demo-card { padding: 19px; }
.status-card h2, .demo-card h2 { font-size: 22px; }
.stage-list { margin: 18px 0 0; padding: 0; list-style: none; }
.stage-list li { position: relative; display: grid; grid-template-columns: 19px minmax(0, 1fr); align-items: center; column-gap: 8px; padding: 0 0 16px; color: #92998f; font-size: 10px; }
.stage-list li:not(:last-child)::after { position: absolute; top: 17px; bottom: 0; left: 8px; width: 1px; background: #e7e9e1; content: ""; }
.stage-list li.active { color: var(--forest); font-weight: 600; }
.stage-list li.done { color: #586c59; }
.stage-mark { position: relative; z-index: 1; width: 17px; height: 17px; display: grid; place-items: center; border: 1px solid #dfe2d9; border-radius: 50%; background: var(--surface); color: var(--forest); font: 9px var(--sans); }
.stage-list li small { grid-column: 2; margin-top: 4px; color: #858e83; font-size: 8px; font-weight: 400; }
.spinner { width: 7px; height: 7px; border: 1px solid #aabaaa; border-top-color: var(--forest); border-radius: 50%; animation: spin .8s linear infinite; }
@keyframes spin { to { transform: rotate(360deg); } }
.server-note { padding-top: 11px; border-top: 1px solid #eceee7; color: #858d83; font-size: 8px; line-height: 1.55; }
.demo-card { background: #faf9f5; }
.demo-card > p { margin: 8px 0 13px; color: var(--muted); font-size: 10px; line-height: 1.55; }
.demo-actions { display: grid; gap: 6px; }
.demo-actions button { display: flex; align-items: center; justify-content: space-between; gap: 8px; padding: 9px 10px; border: 1px solid var(--line); border-radius: 4px; background: #fffefa; color: #48564a; text-align: left; font-size: 9px; transition: border-color .16s ease, background .16s ease; }
.demo-actions button:hover { border-color: #c4d1c3; background: #f5f8f3; }
.demo-actions button span { color: #7c857a; font-size: 8px; }
.demo-foot { margin-top: 10px; color: #979c94; font-size: 8px; line-height: 1.5; }
.deployment-note { margin-top: 13px; padding: 10px 12px; border: 1px solid #e8dcc3; border-radius: 5px; background: #fcf7eb; color: #765c2d; font-size: 9px; line-height: 1.5; }

.demo-section { padding: 20px 0 8px; }
.section-heading { align-items: end; margin-bottom: 15px; }
.section-heading h2 { font-size: 29px; }
.section-heading > p { max-width: 300px; margin: 0 0 2px; color: var(--muted); font-size: 10px; line-height: 1.5; }
.scenario-grid { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 11px; }
.scenario-card { min-width: 0; min-height: 197px; display: flex; flex-direction: column; align-items: flex-start; padding: 17px 17px 14px; border: 1px solid var(--line); border-radius: 7px; background: var(--surface); color: var(--ink); text-align: left; transition: border-color .17s ease, background .17s ease, transform .17s ease; }
.scenario-card:hover { transform: translateY(-2px); border-color: #b9c8b8; }
.scenario-card.selected { border-color: #69856c; background: #f8fbf6; }
.scenario-index { color: #858e83; font-size: 8px; }
.scenario-card > strong { margin-top: 20px; color: var(--forest); font: 500 31px/1 var(--serif); letter-spacing: -.035em; }
.scenario-review > strong { color: #805f2a; font-size: 26px; }
.scenario-title { margin-top: 5px; color: #344137; font-size: 11px; font-weight: 600; }
.scenario-copy { max-width: 260px; margin-top: 6px; color: var(--muted); font-size: 9px; line-height: 1.5; }
.scenario-link { display: flex; justify-content: space-between; width: 100%; margin-top: auto; padding-top: 13px; border-top: 1px solid #eceee7; color: #536d57; font-size: 8px; font-weight: 600; }
.scenario-link b { font-size: 11px; font-weight: 500; }
.demo-disclosure { display: flex; align-items: flex-start; gap: 9px; margin-top: 12px; padding: 10px 11px; border: 1px solid #e4e7dc; border-radius: 5px; background: #f9f9f4; color: #71796e; font-size: 9px; line-height: 1.5; }
.demo-disclosure strong { color: #465b48; }
.demo-disclosure-mark { width: 15px; height: 15px; display: grid; flex: 0 0 auto; place-items: center; border: 1px solid #b9c2b5; border-radius: 50%; color: #6a7b68; font: 600 9px var(--serif); }

.results { margin-top: 22px; scroll-margin-top: 18px; }
.case-evaluation { margin: 0 0 13px; padding: 17px 20px; border-color: #dce4d9; background: #fffefa; }
.case-evaluation-heading { display: flex; align-items: center; justify-content: space-between; gap: 14px; }
.case-evaluation-heading h2 { margin: 5px 0 0; color: var(--ink); font: 500 22px/1.1 var(--serif); }
.case-evaluation-heading > strong { padding: 7px 9px; border: 1px solid #d5dfd3; border-radius: 4px; color: #455f49; font-size: 9px; }
.evaluation-needs_review { border-color: #e8d9b8; background: #fffdf8; }
.evaluation-needs_review .case-evaluation-heading > strong { border-color: #e8d9b8; background: #fcf5e7; color: #805e25; }
.evaluation-rejected { border-color: #ead5d0; background: #fffaf8; }
.evaluation-rejected .case-evaluation-heading > strong { border-color: #ead5d0; background: #fff2ef; color: #80483e; }
.case-evaluation > p { margin: 8px 0 0; color: #70796f; font-size: 9px; line-height: 1.5; }
.evaluation-counts { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 8px; margin: 12px 0 0; }
.evaluation-counts > div { padding: 8px 10px; border: 1px solid #e7eae3; border-radius: 4px; background: #fff; }
.evaluation-counts dt { color: #7c857a; font-size: 8px; }
.evaluation-counts dd { margin: 4px 0 0; color: #344137; font: 500 18px var(--serif); }
.evaluation-counts .count-alert { border-color: #ead5d0; background: #fff7f4; }
.evaluation-counts .count-alert dd { color: #8b4c42; }
.case-evaluation .evaluation-alert { color: #80483e; font-size: 9px; }
.case-evaluation .evaluation-alert p { margin: 8px 0 0; font-weight: 600; }
.case-evaluation .evaluation-alert ul { margin: 5px 0 0; padding-left: 17px; }
.case-evaluation .evaluation-alert li { margin: 3px 0; line-height: 1.45; }
.case-evaluation > a { display: inline-flex; gap: 8px; margin-top: 10px; color: var(--forest); font-size: 9px; font-weight: 600; text-decoration: none; }
.case-evaluation > a:hover { text-decoration: underline; }
.report-action { display: flex; justify-content: flex-end; margin-bottom: 10px; }
.investigation-report { margin-bottom: 14px; padding: 25px 28px; border: 1px solid #dfe5dc; border-radius: 8px; background: #fff; color: #303a31; }
.report-heading { display: flex; justify-content: space-between; align-items: flex-start; gap: 18px; padding-bottom: 17px; border-bottom: 2px solid #344b38; }
.report-heading h2 { margin: 7px 0 4px; font: 500 29px/1.1 var(--serif); }
.report-heading p, .investigation-report p { color: #677168; font-size: 10px; line-height: 1.55; }
.report-heading p { margin: 0; }
.report-disposition { padding: 7px 9px; border: 1px solid #d5dfd3; border-radius: 4px; color: #455f49; font-size: 9px; font-weight: 700; }
.report-synthetic { margin: 13px 0 0; padding: 9px 11px; border: 1px solid #e8d8b4; background: #fcf6e8; color: #765923 !important; font-weight: 700; }
.report-meta { display: grid; grid-template-columns: 1fr 1fr 1fr; gap: 12px; padding: 15px 0; border-bottom: 1px solid #e7eae3; }
.report-meta div { display: grid; gap: 5px; min-width: 0; }
.report-meta strong, .investigation-report h3 { color: #50634f; font-size: 9px; letter-spacing: .07em; text-transform: uppercase; }
.report-meta span { overflow-wrap: anywhere; font-size: 10px; }
.investigation-report section { padding: 13px 0; border-bottom: 1px solid #e7eae3; }
.investigation-report h3 { margin: 0 0 9px; }
.report-amount { margin: 4px 0 11px; color: #344b38 !important; font: 500 24px var(--serif) !important; }
.report-comparison { display: grid; gap: 5px; margin: 8px 0; padding: 10px 12px; border: 1px solid #e5e9e2; background: #fafbf8; font-size: 10px; }
.report-comparison small { color: #70796f; }
.report-caution { padding: 9px 11px; border-left: 3px solid #b68b41; background: #fcf7ed; color: #705728 !important; }
.report-audit { margin: 8px 0; font-size: 10px; }
.report-audit > p { margin: 5px 0; }
.report-audit ul, .investigation-report section > ul { padding-left: 18px; }
.report-audit li, .investigation-report section > ul li { margin: 5px 0; font-size: 9px; line-height: 1.5; }
.report-evidence { display: grid; grid-template-columns: 1fr 1fr; gap: 8px; }
