  if (disabled) return <main className="shell"><header className="topbar"><Link className="brand" href="/">MarginGhost</Link></header><section className="card" style={{ maxWidth: 620, margin: "64px auto", padding: 28 }}><div className="step">JUDGE PREVIEW</div><h1>Preview access is unavailable</h1><p>Judge preview is disabled or its security configuration is incomplete. Public synthetic examples remain available.</p><Link className="secondary-button" href="/demo">Open synthetic demo →</Link></section></main>;
  return <main className="shell"><header className="topbar"><Link className="brand" href="/">MarginGhost</Link><Link href="/demo">Synthetic demo</Link></header><section className="card" style={{ maxWidth: 620, margin: "64px auto", padding: 28 }}><div className="step">INVITED JUDGES</div><h1>Sign in to Judge Preview</h1><p>Use the preview password provided to invited neatHack judges.</p><div role="note" className="deployment-note"><strong>Hackathon preview only.</strong> Do not upload confidential, personal, or real customer financial information. Uploaded documents are processed for this session and must be synthetic or approved for demonstration use.</div><form onSubmit={login} style={{ marginTop: 22 }}>{signedIn ? <><p role="status">You are signed in.</p><Link className="primary-button" href="/investigate">Continue to investigations →</Link></> : <><label htmlFor="judge-password">Preview password</label><input id="judge-password" type="password" autoComplete="current-password" required maxLength={256} value={password} onChange={event => setPassword(event.target.value)} style={{ display: "block", width: "100%", margin: "8px 0 16px", padding: 12 }} /><button className="primary-button" disabled={busy || disabled}>{busy ? "Signing in…" : "Sign in"}</button>{error && <p role="alert">{error}</p>}</>}</form></section></main>;
}
