.self-audit-disposition { flex: 0 0 auto; padding: 7px 9px; border: 1px solid #cfddcd; border-radius: 4px; background: #f0f5ee; color: #49684d; font-size: 10px; font-weight: 750; letter-spacing: .07em; }
.audit-needs_review { border-color: #e8d9b8; background: #fffdf8; }
.audit-needs_review .self-audit-disposition { border-color: #e8d9b8; background: #fcf5e7; color: #805e25; }
.audit-rejected .self-audit-disposition { border-color: #dfe2d9; background: #f4f4ef; color: #636d61; }
.self-audit-proposal { margin: 15px 0 4px; color: #344137; font-size: 14px; font-weight: 650; line-height: 1.45; }
.self-audit-explanation { margin: 0; color: #687368; font-size: 12px; line-height: 1.55; }
.self-audit-checks { display: grid; gap: 0; margin: 15px 0 0; padding: 0; list-style: none; border-top: 1px solid #eceee7; }
.self-audit-checks li { display: grid; grid-template-columns: 24px minmax(0, 1fr) auto; align-items: start; gap: 10px; padding: 12px 0; border-bottom: 1px solid #eceee7; }
.check-status { width: 22px; height: 22px; display: grid; place-items: center; border: 1px solid #cddccc; border-radius: 50%; background: #f0f5ee; color: #476b4b; font-size: 13px; font-weight: 700; }
.check-status.check-failed { border-color: #ead5d0; background: #fff5f2; color: #8a4e43; }
.check-status.check-not_verified { border-color: #e8dcc3; background: #fcf7eb; color: #806437; }
.self-audit-checks li strong { color: #344137; font-size: 12px; }
.self-audit-checks li p { margin: 3px 0 0; color: #737c72; font-size: 11px; line-height: 1.5; }
.check-label { padding-top: 3px; color: #557159; font-size: 9px; font-weight: 750; letter-spacing: .05em; }
.check-label.check-failed { color: #8a4e43; }
.check-label.check-not_verified { color: #806437; }
.self-audit-references { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 13px; margin-top: 13px; }
.self-audit-references > div strong { color: #4c5d4e; font-size: 11px; }
.self-audit-references p { margin: 5px 0 0; color: #687368; font-size: 11px; line-height: 1.55; overflow-wrap: anywhere; }
.self-audit-disclaimer { margin-top: 14px; padding: 10px 12px; border: 1px solid #e5e6dc; border-radius: 4px; background: #f8f8f2; color: #687164; font-size: 11px; line-height: 1.5; }
.finding-row { margin-top: 14px; padding: 14px 0 4px; border-top: 1px solid #eceee8; }
.finding-head { display: flex; align-items: center; justify-content: space-between; gap: 12px; }
.finding-head > strong { font-size: 10px; }
.finding-head > strong span { color: #aeb4ab; }
.finding-tag { padding: 5px 7px; border-radius: 3px; background: #f8f0df; color: #805e25; font-size: 7px; font-weight: 700; letter-spacing: .04em; }
.review-tag { background: #f8eeeb; color: #8a4e43; }
.finding-row > p { margin: 8px 0 11px; color: #6e786d; font-size: 9px; line-height: 1.5; }
.comparison { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 8px; padding: 11px; border: 1px solid #eceee8; border-radius: 5px; background: #fafaf6; }
.comparison > div { min-width: 0; padding: 2px 3px; }
.comparison small { display: block; margin-bottom: 5px; color: #858e83; font-size: 8px; }
.comparison strong { color: #354238; font-size: 10px; overflow-wrap: anywhere; }
.comparison > b { display: none; }
.line-total { border-left: 1px solid #e2e6dc; padding-left: 11px !important; }
.line-total strong { color: var(--forest); }
.review-empty { display: grid; gap: 5px; margin-top: 14px; padding: 14px; border: 1px solid #eadfc8; border-radius: 5px; background: #fcf7eb; color: #725a31; font-size: 10px; }
.review-empty span { color: #847456; font-size: 9px; }
.zero-findings { display: flex; align-items: flex-start; gap: 10px; margin-top: 14px; padding: 14px 0 1px; border-top: 1px solid #eceee8; }
.zero-check { width: 22px; height: 22px; display: grid; flex: 0 0 auto; place-items: center; border: 1px solid #d8e3d6; border-radius: 50%; background: #f0f5ee; color: var(--forest); font-size: 11px; }
.zero-findings strong { font-size: 10px; }
.zero-findings p { margin: 4px 0 0; color: #818b80; font-size: 9px; line-height: 1.5; }
.warnings-box { margin-top: 11px; }
.evidence-toolbar { display: flex; align-items: flex-end; justify-content: space-between; gap: 20px; }
.evidence-toolbar p { margin: 5px 0 0; color: #858e83; font-size: 9px; line-height: 1.5; }
.source-count { padding: 6px 8px; border: 1px solid var(--line); border-radius: 99px; color: #747e73; font-size: 8px; white-space: nowrap; }
.search-box { min-height: 34px; display: flex; align-items: center; gap: 7px; padding: 0 9px; border: 1px solid var(--line); border-radius: 5px; background: #fff; color: #798278; }
.search-box input { width: 165px; min-width: 0; border: 0; outline: 0; background: transparent; color: var(--ink); font-size: 9px; }
.search-box input::placeholder { color: #9ba198; }
.evidence-list { margin-top: 13px; border-top: 1px solid #eceee8; }
.source-group { border-bottom: 1px solid #eceee8; }
.source-group summary { display: flex; align-items: center; gap: 10px; min-height: 55px; cursor: pointer; list-style: none; }
.source-group summary::-webkit-details-marker { display: none; }
.source-doc-mark { width: 25px; height: 27px; }
.source-doc-title { display: grid; gap: 2px; min-width: 0; }
.source-doc-title strong { color: #344137; font-size: 9px; }
.source-doc-title small { color: #8d958b; font-size: 8px; }
.source-pages { margin-left: auto; color: #858e83; font-size: 8px; letter-spacing: .02em; text-transform: none; }
.source-chevron { margin-left: 5px; color: #6c796d; font-size: 14px; transition: transform .15s ease; }
.source-group[open] .source-chevron { transform: rotate(180deg); }
.source-excerpts { padding: 0 0 8px 35px; }
.evidence-item { padding: 10px 0; border-top: 1px solid #f0f1eb; }
.evidence-meta { display: flex; flex-wrap: wrap; gap: 11px; color: #8c958a; font-size: 7px; letter-spacing: .055em; }
.evidence-item blockquote { margin: 6px 0 0; color: #4b574d; font: 10px/1.65 ui-monospace, SFMono-Regular, Consolas, monospace; overflow-wrap: anywhere; }
.empty-evidence { padding: 16px 0; color: #858e83; font-size: 9px; }
.disclaimer { padding: 12px 0 8px; color: #858e83; text-align: center; font-size: 8px; }
.method-note { display: flex; align-items: baseline; gap: 18px; margin: 23px 0 19px; padding: 14px 0; border-top: 1px solid var(--line); border-bottom: 1px solid var(--line); }
.method-note p { max-width: 720px; margin: 0; color: #70796f; font-size: 9px; line-height: 1.55; }
footer { display: flex; justify-content: space-between; gap: 14px; padding: 20px 0 27px; color: #858e83; font-size: 8px; }
footer > span:first-child { color: #59655b; font-weight: 700; }

@media (max-width: 900px) {
  .shell { width: min(100% - 42px, 760px); }
  .product-hero-grid { grid-template-columns: minmax(0, 1fr) 250px; gap: 25px; }
  .workspace { grid-template-columns: minmax(0, 1fr); }
  .side-column { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .demo-section { padding-top: 13px; }
}
@media (max-width: 640px) {
  .shell { width: calc(100% - 32px); }
  .topbar { min-height: 61px; gap: 10px; flex-wrap: wrap; padding: 11px 0; }
  .main-nav { order: 3; width: 100%; justify-content: space-between; gap: 10px; margin: 1px 0 0; }
  .nav-cta { margin-left: auto; }
  .product-hero { padding: 35px 0 30px; }
  .product-hero-grid { grid-template-columns: minmax(0, 1fr); }
  .hero-proof { max-width: 420px; }
  .how-grid { grid-template-columns: minmax(0, 1fr); }
  .how-card { min-height: auto; }
  .product-cta { align-items: flex-start; flex-direction: column; }
  .brand { gap: 8px; font-size: 13px; }
  .brand-icon { width: 26px; height: 26px; }
  .main-nav { gap: 13px; }
  .main-nav a { font-size: 9px; }
  .main-nav a:nth-child(3) { display: none; }
  .mode-pill { gap: 5px; padding: 6px 7px; font-size: 8px; }
  .hero { padding: 34px 0 28px; }
  .hero h1 { max-width: 520px; font-size: clamp(39px, 11vw, 52px); }
  .hero > p { font-size: 12px; }
  .section-heading { display: block; }
  .section-heading h2 { font-size: 25px; }
  .section-heading > p { margin-top: 6px; }
  .scenario-grid { grid-template-columns: 1fr; gap: 8px; }
  .scenario-card { min-height: 0; display: grid; grid-template-columns: minmax(0, 1fr) auto; align-items: center; column-gap: 12px; padding: 13px; }
  .scenario-index, .scenario-title, .scenario-copy { grid-column: 1; }
  .scenario-card > strong { grid-column: 1; margin-top: 9px; font-size: 27px; }
  .scenario-review > strong { font-size: 23px; }
  .scenario-title { margin-top: 4px; }
  .scenario-copy { margin-top: 4px; }
  .scenario-link { grid-column: 2; grid-row: 1 / span 4; width: auto; min-width: 90px; align-self: stretch; align-items: center; gap: 8px; margin: 0; padding: 0 0 0 10px; border-top: 0; border-left: 1px solid #eceee7; }
  .upload-card { padding: 17px; }
  .upload-card { grid-template-columns: 1fr; }
  .doc-invoice { grid-column: auto; }
  .section-head h2, .status-card h2, .demo-card h2, .evidence-card h2 { font-size: 22px; }
  .doc-group { padding: 11px; }
  .file-row { flex-wrap: wrap; }
  .file-main { flex-basis: calc(100% - 42px); }
  .row-actions { margin-left: 37px; }
  .id-label { align-items: flex-start; flex-direction: column; }
  .id-label input { width: 100%; max-width: 230px; }
  .side-column { grid-template-columns: 1fr; }
  .status-card, .demo-card { padding: 16px; }
  .submit-row { align-items: flex-start; flex-direction: column; }
  .metric-grid { grid-template-columns: 1fr; gap: 7px; }
  .metric-card { padding: 11px 13px; }
  .metric-card strong, .metric-primary strong { margin: 5px 0 3px; font-size: 27px; }
  .review-banner ~ .metric-grid .metric-primary strong { font-size: 24px; }
  .result-banner { padding: 15px; }
  .result-banner h2 { font-size: 24px; }
  .findings-card, .evidence-card { padding: 15px; }
  .self-audit-card { padding: 15px; }
  .case-evaluation { padding: 15px; }
  .evaluation-counts { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .self-audit-checks li { grid-template-columns: 22px minmax(0, 1fr); }
  .check-label { grid-column: 2; padding-top: 0; }
  .self-audit-references { grid-template-columns: 1fr; }
  .comparison { grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 6px; }
  .line-total { border-left: 0; padding-left: 3px !important; }
  .evidence-toolbar { align-items: stretch; flex-direction: column; gap: 11px; }
  .evidence-toolbar .search-box { width: 100%; }
  .evidence-toolbar .search-box input { flex: 1; width: 100%; }
  .source-excerpts { padding-left: 4px; }
  .source-pages { font-size: 7px; }
  .method-note { align-items: flex-start; flex-direction: column; gap: 6px; }
  footer { align-items: flex-start; }
}
@media (max-width: 390px) {
  .shell { width: calc(100% - 24px); }
  .topbar { flex-wrap: wrap; padding: 9px 0; }
  .main-nav { order: 3; width: 100%; justify-content: flex-start; padding: 3px 0 0 34px; }
  .main-nav a:nth-child(3) { display: inline; }
  .scenario-link { min-width: 72px; font-size: 7px; }
  .result-banner { flex-direction: column; }
  .status-chip { align-self: flex-start; }
  .comparison { grid-template-columns: 1fr 1fr; }
  .source-pages { display: none; }
}
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { scroll-behavior: auto !important; animation-duration: .01ms !important; transition-duration: .01ms !important; }
}

@media print {
  @page { size: A4; margin: 15mm; }
  body { background: #fff !important; color: #111 !important; print-color-adjust: exact; -webkit-print-color-adjust: exact; }
  .shell > :not(#results), #results > :not(.investigation-report), .report-action { display: none !important; }
  #results { display: block !important; margin: 0; }
  .investigation-report { display: block !important; margin: 0; padding: 0; border: 0; border-radius: 0; font-size: 9pt; }
  .investigation-report h2 { font-size: 23pt; }
  .investigation-report h3 { break-after: avoid; }
  .report-audit, .report-comparison, .report-evidence blockquote, .report-contradictions blockquote { break-inside: avoid; }
  .report-evidence { grid-template-columns: 1fr; }
  .report-meta { grid-template-columns: 1fr 1fr 1fr; }
  a { color: inherit; text-decoration: none; }
}
@media (max-width: 640px) {
  .report-heading { flex-direction: column; }
  .report-meta, .report-evidence { grid-template-columns: 1fr; }
  .investigation-report { padding: 17px; }
}

/* Public launch homepage */
.mg-home {
  --mg-bg: #080f0d;
  --mg-surface: #101c18;
  --mg-card: #15241e;
  --mg-mint: #b5f0bd;
  --mg-emerald: #184f3b;
  --mg-text: #f5f7f2;
  --mg-muted: #a2b2a9;
import HomeClient from "../home-client";

export default function DemoPage() {
  return <HomeClient demoMode />;
}
"use client";
import { useRouter } from "next/navigation";

export default function JudgeLogoutButton() {
  const router = useRouter();
  return <button type="button" className="text-action" onClick={async () => { await fetch("/api/judge-preview/logout", { method: "POST" }); router.push("/judge-preview"); }}>Sign out</button>;
}

output.text:
:root {
  color-scheme: light;
  --paper: #f5f4ef;
  --surface: #fffefa;
  --surface-muted: #f9f8f3;
  --ink: #222b25;
  --muted: #737b73;
  --subtle: #969c94;
  --line: #e4e5dc;
  --line-strong: #d5d9cf;
  --forest: #234d3a;
  --forest-deep: #183a2a;
  --forest-wash: #edf3ed;
  --amber: #855c1d;
  --amber-wash: #fbf4e6;
  --red: #8b4c42;
  --red-wash: #faf0ed;
  --sans: "Aptos", "Segoe UI", Arial, sans-serif;
  --serif: "Iowan Old Style", "Palatino Linotype", "Book Antiqua", Georgia, serif;
  font-family: var(--sans);
  background: var(--paper);
  color: var(--ink);
  font-synthesis: none;
  text-rendering: optimizeLegibility;
}

* { box-sizing: border-box; }
html { scroll-behavior: smooth; scroll-padding-top: 26px; }
body { margin: 0; min-width: 320px; background: var(--paper); }
button, input { font: inherit; }
button { cursor: pointer; }
a { color: inherit; }
button:focus-visible, a:focus-visible, input:focus-visible, summary:focus-visible {
  outline: 3px solid #8ba991;
  outline-offset: 3px;
}
::selection { background: #dce8dc; color: var(--forest-deep); }

.shell { width: min(1160px, 100% - 64px); margin: 0 auto; }
.topbar {
  min-height: 70px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 24px;
  border-bottom: 1px solid var(--line);
}
.brand { display: inline-flex; align-items: center; gap: 10px; color: var(--ink); text-decoration: none; font-size: 15px; font-weight: 700; letter-spacing: -.45px; white-space: nowrap; }
.brand small, footer small { margin-left: 4px; color: var(--subtle); font: 500 9px var(--sans); letter-spacing: .02em; }
.brand-icon { width: 29px; height: 29px; display: grid; place-items: center; border-radius: 7px; background: var(--forest); color: #fff; font: 500 17px var(--serif); }
.main-nav { display: flex; align-items: center; gap: 29px; margin-left: auto; }
.main-nav a { color: #606a61; text-decoration: none; font-size: 11px; transition: color .16s ease; }
.main-nav a:hover { color: var(--forest); }
.mode-pill { display: inline-flex; align-items: center; gap: 7px; padding: 7px 10px; border: 1px solid #d6e0d6; border-radius: 99px; background: #f6faf5; color: var(--forest); font-size: 9px; font-weight: 600; white-space: nowrap; }
.mode-pill i { width: 6px; height: 6px; border-radius: 50%; background: #568162; }
.local-pill { border-color: var(--line); background: var(--surface); color: #606a61; }
.local-pill i { background: #8a9589; }

.hero { max-width: 780px; padding: 48px 0 37px; }
.eyebrow, .step, .scenario-index, .evidence-meta, .source-pages { font-size: 9px; font-weight: 600; letter-spacing: .09em; text-transform: uppercase; }
.eyebrow { display: flex; align-items: center; gap: 9px; color: var(--forest); }
.dot { width: 6px; height: 6px; border-radius: 50%; background: #6a9273; }
.hero h1 { max-width: 750px; margin: 15px 0 9px; color: #202922; font: 400 clamp(40px, 5.5vw, 61px)/.99 var(--serif); letter-spacing: -.045em; }
.hero > p { max-width: 580px; margin: 0; color: #626c63; font-size: 14px; line-height: 1.65; }
.hero-action { display: inline-flex !important; width: max-content; margin-top: 20px; text-decoration: none; }
.hero-note { display: flex; align-items: center; gap: 9px; margin-top: 13px; color: var(--subtle); font-size: 9px; }
.hero-note span { color: #b7bcb4; }
.nav-cta { display: inline-flex; align-items: center; gap: 10px; padding: 9px 12px; border: 1px solid #d7e1d6; border-radius: 5px; color: var(--forest); text-decoration: none; font-size: 10px; font-weight: 600; white-space: nowrap; }
.nav-cta:hover, .secondary-button:hover { background: #f1f6f0; }
.product-hero { padding: 54px 0 50px; }
.product-hero-grid { display: grid; grid-template-columns: minmax(0, 1.5fr) minmax(260px, .7fr); align-items: center; gap: clamp(30px, 7vw, 90px); margin-top: 17px; }
.product-hero h1 { max-width: 690px; margin: 0; color: #202922; font: 400 clamp(44px, 6.6vw, 74px)/.98 var(--serif); letter-spacing: -.05em; }
.product-hero-grid > div > p { max-width: 550px; margin: 18px 0 0; color: #626c63; font-size: 14px; line-height: 1.7; }
.product-actions { display: flex; align-items: center; flex-wrap: wrap; gap: 12px; margin-top: 21px; }
.secondary-button { min-height: 40px; display: inline-flex; align-items: center; gap: 15px; padding: 0 14px; border: 1px solid var(--line-strong); border-radius: 5px; color: #4d6250; text-decoration: none; font-size: 10px; font-weight: 600; }
.hero-proof { padding: 21px; border: 1px solid #dfe5dc; border-radius: 8px; background: #fbfcf8; box-shadow: 0 12px 36px #273d2610; }
.proof-label { color: #7c887c; font-size: 8px; font-weight: 700; letter-spacing: .1em; }
.proof-amount { margin-top: 20px; color: var(--forest); font: 500 43px/1 var(--serif); letter-spacing: -.04em; }
.hero-proof > strong { display: block; margin-top: 6px; color: #344137; font-size: 11px; }
.hero-proof > p { margin: 6px 0 14px; color: #798278; font-size: 9px; line-height: 1.55; }
.proof-rule { display: flex; justify-content: space-between; gap: 12px; padding: 9px 0; border-top: 1px solid #e9ece5; color: #818a80; font-size: 8px; }
.proof-rule b { color: #455448; font-weight: 600; text-align: right; }
.hero-proof > small { display: block; margin-top: 10px; color: #979e94; font-size: 7px; }
.how-section { padding: 25px 0 40px; border-top: 1px solid var(--line); }
.how-section .section-heading h2 { font-size: 31px; }
.how-grid { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 12px; }
.how-card { min-height: 150px; padding: 17px; border: 1px solid var(--line); border-radius: 7px; background: var(--surface); }
.how-card > span { color: #6e886f; font: 500 19px var(--serif); }
.how-card h3 { margin: 14px 0 5px; color: #344137; font: 500 18px var(--serif); }
.how-card p { max-width: 300px; margin: 0; color: #778075; font-size: 9px; line-height: 1.65; }
.product-cta { display: flex; align-items: center; justify-content: space-between; gap: 28px; margin: 9px 0 12px; padding: 21px; border: 1px solid #dce5da; border-radius: 8px; background: #f1f5ee; }
.product-cta h2 { margin: 6px 0 5px; color: #28372c; font: 500 25px var(--serif); }
.product-cta p { max-width: 470px; margin: 0; color: #737e72; font-size: 9px; line-height: 1.55; }
.product-cta .product-actions { flex: 0 0 auto; margin: 0; }
.primary-button { min-height: 40px; display: inline-flex; align-items: center; justify-content: center; gap: 18px; padding: 0 16px; border: 1px solid var(--forest); border-radius: 5px; background: var(--forest); color: #fff; font-size: 11px; font-weight: 600; transition: background .16s ease, border-color .16s ease, transform .16s ease; }
.primary-button:hover:not(:disabled) { transform: translateY(-1px); border-color: var(--forest-deep); background: var(--forest-deep); }
.primary-button:disabled { opacity: .48; cursor: not-allowed; }

.workspace { display: grid; grid-template-columns: minmax(0, 1.55fr) minmax(270px, .8fr); gap: 18px; align-items: start; }
.card { border: 1px solid var(--line); border-radius: 9px; background: var(--surface); }
.upload-card { padding: 23px 24px; }
.section-head, .section-heading { display: flex; align-items: flex-start; justify-content: space-between; gap: 20px; }
.step { color: #7c887c; }
.section-head h2, .section-heading h2, .status-card h2, .demo-card h2, .evidence-card h2 { margin: 5px 0 0; color: var(--ink); font: 500 24px/1.1 var(--serif); letter-spacing: -.025em; }
.quiet-pill { align-self: flex-start; padding: 6px 9px; border: 1px solid var(--line); border-radius: 99px; color: #717a70; font-size: 9px; white-space: nowrap; }
